import subprocess, random, re
ORIG="/workspace/Homework/DS02_String"; MINE="/tmp/build/verify-DS02_String"; REF="/tmp/build/ref-DS02_String"
def run(cp, raw, pat):
    p=subprocess.run(["java","-cp",cp,"DS_String"],input=(raw+"\n"+pat+"\n").encode(),
                     stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=20)
    return p.stdout.decode("utf-8","replace")
def norm_exact(o):   # only line numbers normalized -> mine vs ref must be identical
    return re.sub(r"DS_String\.java:\d+","L",o)
def norm_sem(o):     # semantic: verdict lines + exception class, drop JVM local-slot naming
    o=re.sub(r"DS_String\.java:\d+","L",o)
    o=re.sub(r'because "<local\d+>"','because "<local>"',o)
    return o
cases=[]
al="abcdefg"
for L in range(0,21):
    raw="".join(al[i%len(al)] for i in range(L))
    for plen in range(1,7):
        for off in range(0,5):
            if off+plen<=L: cases.append((raw,raw[off:off+plen]))
    cases += [(raw,"z"),(raw,"zz"),(raw,""),(raw,raw+"x"),(raw,"\0"),(raw,"a\0")]
cases += [("数据结构与算法","结构与"),("数据结构与算法","队列"),("数据结构与算法","数据结构与算法"),
          ("数据结构与算法","算法"),("数据结构","数据结构"),("数据结构","构"),("",""),("","a"),("a","")]
random.seed(99)
for _ in range(500):
    raw="".join(random.choice("ab") for _ in range(random.randint(0,14)))
    pat="".join(random.choice("ab") for _ in range(random.randint(1,6)))
    cases.append((raw,pat))
dm=dr=0; n=0
