    if norm_sem(m)!=norm_sem(o):
        dm+=1
        if dm<=5: print("MINE!=ORIG(semantic) raw=%r pat=%r\n M=%r\n O=%r"%(raw,pat,m,o))
print("cases=%d  mine_vs_ref_exact_diffs=%d  mine_vs_orig_semantic_diffs=%d"%(n,dr,dm))
